#include "path.hpp"
#include <unordered_map>
#include <deque>
string ciphertext;int innerwidth;long evaluations=0;unordered_map<string,float>memo;
string fingerprint(Key k){string s;for(int v:k)s.push_back(char(v));return s;}
float fitness(Key physical){string sig=fingerprint(physical);auto it=memo.find(sig);if(it!=memo.end())return it->second;float z=reconstruct(dec(ciphertext,inverseKey(physical)),innerwidth).score;memo[sig]=z;evaluations++;return z;}
Key mutate(Key k){int w=k.size(),a=rng()%w,b=rng()%w;if(a>b)swap(a,b);switch(rng()%4){case 0:swap(k[a],k[b]);break;case 1:reverse(k.begin()+a,k.begin()+b+1);break;default:if(a<b){int c=a+1+rng()%(b-a);rotate(k.begin()+a,k.begin()+c,k.begin()+b+1);}}return k;}
Key crossover(Key a,Key b){int w=a.size(),x=rng()%w,y=rng()%w;if(x>y)swap(x,y);Key k(w,-1);vector<bool>used(w,false);for(int i=x;i<=y;i++){k[i]=a[i];used[a[i]]=true;}int pos=(y+1)%w;for(int i=0;i<w;i++){int v=b[(y+1+i)%w];if(!used[v]){while(k[pos]!=-1)pos=(pos+1)%w;k[pos]=v;used[v]=true;}}return k;}
void report(Cand c){Key outer=inverseKey(c.k);auto middle=dec(ciphertext,outer);auto path=reconstruct(middle,innerwidth);Key inner(innerwidth);for(int i=0;i<innerwidth;i++)inner[path.cols[i]]=i;cout<<"RESULT score="<<c.sc<<" inner=";for(int v:inner)cout<<v<<",";cout<<" outer=";for(int v:outer)cout<<v<<",";cout<<" "<<dec(middle,inner)<<"\n";}
int main(int argc,char**argv){loadTri(argv[1]);loadHigher(argv[1]);ifstream f(argv[2]);f>>ciphertext;innerwidth=stoi(argv[3]);int w=stoi(argv[4]);assert(ciphertext.size()%innerwidth==0);string mode=argv[5];if(mode=="operators"){rng.seed(619403);Key reference(w);iota(reference.begin(),reference.end(),0);for(int t=0;t<10000;t++){Key a=reference,b=reference;shuffle(a.begin(),a.end(),rng);shuffle(b.begin(),b.end(),rng);Key c=crossover(a,b),d=mutate(a);sort(c.begin(),c.end());sort(d.begin(),d.end());assert(c==reference&&d==reference);}cout<<"10000 crossover and mutation permutation checks PASS\n";return 0;}if(mode=="landscape"){ifstream tf(argv[6]);string text;tf>>text;replace(text.begin(),text.end(),',',' ');istringstream ss(text);Key outer;int v;while(ss>>v)outer.push_back(v);assert(outer.size()==w);auto physical=inverseKey(outer);cout<<"truth "<<fitness(physical)<<'\n';report({fitness(physical),physical});for(int i=0;i<w;i++)for(int j=i+1;j<w;j++){auto k=physical;swap(k[i],k[j]);cout<<"swap "<<i<<" "<<j<<" "<<fitness(k)<<'\n';}cout<<"evaluations "<<evaluations<<'\n';return 0;}if(mode=="late"){rng.seed(stoul(argv[6]));int steps=stoi(argv[7]);Key k(w);iota(k.begin(),k.end(),0);shuffle(k.begin(),k.end(),rng);float current=fitness(k);Cand best{current,k};vector<float>history(512,current);deque<string>tabulist;unordered_set<string>tabu;long accepted=0;for(int it=0;it<steps;it++){Key proposal=mutate(k);if(rng()%5==0)proposal=mutate(mutate(proposal));float ns=fitness(proposal);string sig=fingerprint(proposal);int slot=it%history.size();if((!tabu.count(sig)||ns>best.sc)&&(ns>=current||ns>=history[slot])){k=proposal;current=ns;accepted++;tabulist.push_back(sig);tabu.insert(sig);if(tabulist.size()>64){tabu.erase(tabulist.front());tabulist.pop_front();}if(current>best.sc)best={current,k};}history[slot]=current;if(it%1000==0)cout<<"late step "<<it<<" current "<<current<<" best "<<best.sc<<" accepted "<<accepted<<" evaluations "<<evaluations<<'\n'<<flush;}report(best);cout<<"evaluations "<<evaluations<<" accepted "<<accepted<<'\n';return 0;}assert(mode=="blind");rng.seed(stoul(argv[6]));int generations=stoi(argv[7]);int P=40;vector<Cand> pop;Key ident(w);iota(ident.begin(),ident.end(),0);for(int i=0;i<P;i++){auto k=ident;shuffle(k.begin(),k.end(),rng);pop.push_back({fitness(k),k});}auto order=[](const Cand&a,const Cand&b){return a.sc>b.sc;};sort(pop.begin(),pop.end(),order);Cand overall=pop[0];for(int g=0;g<generations;g++){auto tournament=[&](){Cand c=pop[rng()%P];for(int z=0;z<2;z++){auto other=pop[rng()%P];if(other.sc>c.sc)c=other;}return c.k;};vector<Cand> pool=pop;for(int child=0;child<80;child++){Key k=crossover(tournament(),tournament());int changes=1+(rng()%5==0?2:0);for(int z=0;z<changes;z++)k=mutate(k);Cand c{fitness(k),k};if(child%4==0){for(int z=0;z<24;z++){auto proposal=mutate(c.k);float ns=fitness(proposal);if(ns>c.sc)c={ns,proposal};}}pool.push_back(c);}for(int i=0;i<4;i++){auto k=ident;shuffle(k.begin(),k.end(),rng);pool.push_back({fitness(k),k});}sort(pool.begin(),pool.end(),order);pop.clear();set<Key>unique;for(auto c:pool)if(unique.insert(c.k).second){pop.push_back(c);if(pop.size()==P)break;}assert(pop.size()==P);if(pop[0].sc>overall.sc)overall=pop[0];cout<<"generation "<<g<<" best "<<overall.sc<<" evaluations "<<evaluations<<'\n'<<flush;}report(overall);cout<<"evaluations "<<evaluations<<'\n';return 0;}
